<?php declare(strict_types=1);
if(!isset($financeFrameText)){$contributionMessages=isset($nativeAccess)?(new \Kulturhus\Native\Language\Catalog($db,$nativeAccess))->messages():[];$financeFrameText=static fn(string $source,array $values=[]):string=>\Kulturhus\Native\Language\FinanceReceiptMessages::text($source,$contributionMessages,$values);}
$contributionTax=(new \Kulturhus\Verein\Settings($db,(string)$_SESSION['actor']))->section('tax')['data'];
$deductible=$contributionTax['membership_deductible']??'';
$contributionReceipts=(new \Kulturhus\Verein\DonationReceipts($db,(string)$_SESSION['actor']))->listing('money',$r['id']);
$activeContributionReceipts=array_filter($contributionReceipts,fn($receipt)=>!$receipt['cancelled_at']);
?>
<section class="card" data-contribution-payment><h2><?=e($financeFrameText('Mitgliedsbeitrag · Zahlung und Bestätigung'))?></h2>
<p><strong><?= e($financeFrameText(paymentLabel($r['payment_state']))) ?></strong> · <?=e($financeFrameText('{paid} von {total} zugeordnet.',['paid'=>euro((int)$r['allocated_cents']),'total'=>euro((int)$r['amount_cents'])]))?></p>
<?php if($activeContributionReceipts): ?><h3><?=e($financeFrameText('Bereits erstellte Zuwendungsbestätigungen'))?></h3><ul><?php foreach($activeContributionReceipts as $receipt): ?><li><a href="<?= e(url(['view'=>'documents','doc'=>$receipt['document_id']])) ?>"><?=e($financeFrameText('{id} öffnen',['id'=>$receipt['id']]))?></a> · <?=e($financeFrameText('Zur Unterschrift erstellt'))?></li><?php endforeach ?></ul><?php endif ?>
<?php if($deductible==='no'): ?><p><?=e($financeFrameText('Für diesen Verein sind Mitgliedsbeiträge als steuerlich nicht abziehbar hinterlegt. Es wird keine Zuwendungsbestätigung angeboten. Rechnung und zugeordnete Zahlungen dokumentieren den Zahlungseingang.'))?></p>
<?php elseif($deductible!=='yes'): ?><p><?=e($financeFrameText('Die steuerliche Abziehbarkeit der Mitgliedsbeiträge ist noch nicht hinterlegt. Rechnung und Zahlungsstatus bleiben verfügbar. Eine Zuwendungsbestätigung erst nach Klärung in den Steuereinstellungen erstellen.'))?></p>
<?php elseif(in_array($r['payment_state'],['cancelled','reversed'],true)): ?><p><?=e($financeFrameText('Für einen verworfenen oder gegengebuchten Beitrag wird hier keine neue Zuwendungsbestätigung angeboten.'))?></p>
<?php elseif((int)$r['allocated_cents']<=0): ?><p><?=e($financeFrameText('Mitgliedsbeiträge sind als steuerlich abziehbar hinterlegt. Sobald ein Zahlungseingang zugeordnet ist, lässt sich die amtliche Zuwendungsbestätigung vorbereiten.'))?></p>
<?php else: ?><p><?=e($financeFrameText('Mitgliedsbeiträge sind als steuerlich abziehbar hinterlegt. Die amtliche Zuwendungsbestätigung wird für den zugeordneten Beitragszahler vorbereitet. Bei Familienbeiträgen gilt dieselbe Zahlung nicht nochmals für jedes Familienmitglied.'))?></p><?php if($r['payment_state']==='partial'): ?><p><?=e($financeFrameText('Teilzahlung: Nur der tatsächlich eingegangene Betrag kann bestätigt werden. Bei mehreren Zahlungstagen im nächsten Schritt eine Zahlung auswählen.'))?></p><?php endif ?>
<a class="btn btn-outline theme-secondary button secondary" href="<?= e(url(['view'=>'settings','tab'=>'donation-forms','kind'=>'money','source_id'=>$r['id']])) ?>"><?=e($financeFrameText(!$finance->canWrite()?'Zuwendungsformular und Bestätigungen ansehen':($activeContributionReceipts?'Zuwendungsbestätigungen verwalten':'Amtliche Zuwendungsbestätigung vorbereiten')))?></a><p class="muted"><?=e($financeFrameText('Öffnet das vorhandene amtliche Formular 034122. Es wird nichts automatisch ausgestellt, unterschrieben oder versendet. Bereits bescheinigte Zahlungen können nicht doppelt bestätigt werden.'))?></p>
<?php endif ?></section>
